import asyncio,json
from db import connect,now_iso
from common import emit_event,message_json
NICKS={}; CLIENTS=set()
def send(w,line): w.write((line+'\r\n').encode()); return w.drain()
def irc_name(r): return '#'+r['slug']+'/'+r['name']
def find_channel(n):
 if not n.startswith('#') or n[1:].count('/')!=1:return None
 s,ch=n[1:].split('/'); c=connect(); r=c.execute('SELECT c.*,w.slug FROM channels c JOIN workspaces w ON w.id=c.workspace_id WHERE w.slug=? AND c.name=? AND c.is_dm=0',(s,ch)).fetchone(); c.close(); return r
async def handle_client(reader,w):
 state={'pass':None,'nick':None,'user':None,'registered':False,'joined':set(),'sent':set()}
 CLIENTS.add(state)
 async def out(x): await send(w,':huddle '+x)
 async def register():
  if state['registered'] or not state['nick'] or not state.get('real'): return
  c=connect(); u=c.execute('SELECT u.* FROM tokens t JOIN users u ON u.id=t.user_id WHERE t.token=?',(state.get('pass'),)).fetchone(); c.close()
  if not u: await out('464 * :Password incorrect'); w.close(); return
  state['user']=u; state['registered']=True; NICKS[state['nick'].lower()]=state
  n=state['nick']
  for code,text in [('001',f'Welcome to Huddle, {n}'),('002','Your host is huddle'),('003','This server was created today'),('004','huddle huddle 1.0'),('005','CHANTYPES=#')]: await out(f'{code} {n} :{text}')
  await out(f'422 {n} :MOTD File is missing')
 async def names(ch):
  c=connect(); rows=c.execute('SELECT u.username FROM channel_members m JOIN users u ON u.id=m.user_id WHERE m.channel_id=?',(ch['id'],)).fetchall(); c.close()
  vals=[state['nick'] if x['username']==state['user']['username'] else x['username'] for x in rows]
  await out(f'353 {state["nick"]} = {irc_name(ch)} :{" ".join(vals)}'); await out(f'366 {state["nick"]} {irc_name(ch)} :End of /NAMES list')
 try:
  while True:
   raw=await reader.readline()
   if not raw: break
   line=raw.decode(errors='ignore').strip('\r\n'); parts=line.split(' ',2); cmd=parts[0].upper() if parts else ''
   rest=parts[1:] 
   if cmd=='PASS': state['pass']=rest[0] if rest else ''; await register()
   elif cmd=='NICK':
    n=rest[0] if rest else ''
    if n.lower() in NICKS and NICKS[n.lower()] is not state: await out(f'433 * {n} :Nickname is already in use')
    else: state['nick']=n; await register()
   elif cmd=='USER': state['real']=parts[-1].lstrip(':') if len(parts)>1 else ''; await register()
   elif cmd=='PING': await out('PONG huddle :'+(rest[0].lstrip(':') if rest else ''))
   elif cmd=='PONG': pass
   elif cmd=='QUIT': break
   elif not state['registered']: await out(f'451 * :You have not registered')
   elif cmd=='JOIN':
    ch=find_channel(rest[0] if rest else '')
    if not ch: await out(f'403 {state["nick"]} {rest[0] if rest else ""} :No such channel'); continue
    c=connect(); ok=c.execute('SELECT 1 FROM workspace_members WHERE workspace_id=? AND user_id=?',(ch['workspace_id'],state['user']['id'])).fetchone()
    if not ok and ch['is_private']: c.close(); await out(f'403 {state["nick"]} {irc_name(ch)} :No such channel'); continue
    if not ok:c.execute('INSERT OR IGNORE INTO workspace_members VALUES(?,?,?)',(ch['workspace_id'],state['user']['id'],'member'))
    c.execute('INSERT OR IGNORE INTO channel_members VALUES(?,?)',(ch['id'],state['user']['id'])); c.close(); state['joined'].add(ch['id'])
    await out(f':{state["nick"]}!{state["user"]["username"]}@huddle JOIN {irc_name(ch)}')
    await out(f'332 {state["nick"]} {irc_name(ch)} :{ch["topic"]}' if ch['topic'] else f'331 {state["nick"]} {irc_name(ch)} :No topic is set'); await names(ch)
   elif cmd in ('NAMES','TOPIC','WHO','MODE'):
    ch=find_channel(rest[0].split()[0] if rest else '')
    if cmd=='NAMES' and ch: await names(ch)
    elif cmd=='TOPIC' and ch: await out(f'332 {state["nick"]} {irc_name(ch)} :{ch["topic"]}' if ch['topic'] else f'331 {state["nick"]} {irc_name(ch)} :No topic is set')
    elif cmd=='MODE': await out(f'221 {state["nick"]} +' if not ch else f'324 {state["nick"]} {irc_name(ch)} +')
   elif cmd=='PRIVMSG':
    target,text=(rest[0],rest[1].lstrip(':')) if len(rest)>1 else ('','')
    ch=find_channel(target)
    if not ch or ch['id'] not in state['joined']: await out(f'442 {state["nick"]} {target} :You\'re not on that channel'); continue
    c=connect(); c.execute('INSERT INTO messages(channel_id,author_id,body,created_at) VALUES(?,?,?,?)',(ch['id'],state['user']['id'],text,now_iso())); mid=c.execute('SELECT last_insert_rowid()').fetchone()[0]; m=message_json(c,c.execute('SELECT * FROM messages WHERE id=?',(mid,)).fetchone()); c.close(); emit_event(ch['id'],'message.created',{'message':m}); state['sent'].add(mid)
